cd /workspace && python3 <<'EOF'
import csv
expected = {
    'Lambda': {'Ftrue': 112, 'Ffalse': 98, 'Fperc': 53.33, 'Ptrue': 115, 'Pfalse': 95, 'Pperc': 54.76},
    'Compr.': {'Ftrue': 99, 'Ffalse': 111, 'Fperc': 47.14, 'Ptrue': 114, 'Pfalse': 96, 'Pperc': 54.29},
    'MRF': {'Ftrue': 80, 'Ffalse': 130, 'Fperc': 38.10, 'Ptrue': 85, 'Pfalse': 125, 'Pperc': 40.48}
}
with open('ICSE2024-funcConstructs-Artifacts/results/Table-2-descriptive.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        construct = row['Construct']
        if construct == 'lambda':
            key = 'Lambda'
        elif construct == 'comp':
            key = 'Compr.'
        elif construct == 'mrf':
            key = 'MRF'
        else:
            continue
        exp = expected[key]
        ftrue = int(row['Ftrue'])
        ffalse = int(row['Ffalse'])
        fperc = round(float(row['Fperc']), 2)
        ptrue = int(row['Ptrue'])
        pfalse = int(row['Pfalse'])
        pperc = round(float(row['Pperc']), 2)
        errors = []
        if ftrue != exp['Ftrue']:
            errors.append(f"Ftrue mismatch: {ftrue} vs {exp['Ftrue']}")
        if ffalse != exp['Ffalse']:
            errors.append(f"Ffalse mismatch: {ffalse} vs {exp['Ffalse']}")
        if abs(fperc - exp['Fperc']) > 0.01:
            errors.append(f"Fperc mismatch: {fperc} vs {exp['Fperc']}")
        if ptrue != exp['Ptrue']:
            errors.append(f"Ptrue mismatch: {ptrue} vs {exp['Ptrue']}")
        if pfalse != exp['Pfalse']:
            errors.append(f"Pfalse mismatch: {pfalse} vs {exp['Pfalse']}")
        if abs(pperc - exp['Pperc']) > 0.01:
            errors.append(f"Pperc mismatch: {pperc} vs {exp['Pperc']}")
        if errors:
            print(f"ERROR for {key}:")
            for e in errors:
                print("  ", e)
        else:
            print(f"OK: {key} matches expected.")
EOF

